+  static bool is_slli_at(address instr) {
+    assert_cond(instr != nullptr);
+    return extract_opcode(instr) == 0b0010011 &&
+           extract_funct3(instr) == 0b001 &&
+           Assembler::extract(Assembler::ld_instr(instr), 31, 26) == 0b000000;
+  }
